def _run_web_browser_value(self, method: str, /, **params: Any) -> dict[str, Any]:
    self._ensure_method_supported(method)
    rpc_params = dict(params)
    if "timeout_ms" in rpc_params:
        rpc_params["timeout_ms"] = int(rpc_params["timeout_ms"])
    result = self._rpc(method, rpc_params)
    if _business_error(result) != 0:
        if _trace_info(result) in _FATAL_ACTION_TRACES:
            self._raise_business_error(result, method=method)
        ActionResult.from_payload(result).raise_for_error()
    return result

def _run_web_browser_command(self, params: dict[str, Any], *, command: str) -> dict[str, Any]:
    params, error = self._route_user_environment(params)
    if error:
        return error
    if "mode" in params and not _browser_mode_param(params["mode"]):
        return business_error(2, "invalid_params", message="浏览器类型必须为 auto、chrome 或 edge")
    timeout_ms = _int_param(params.get("timeout_ms"), 5000)
    payload = {
        key: value
        for key, value in params.items()
        if value is not None
        and key
        not in {"package_token", "element_id", "state_revision", "package_variables"}
    }
    payload["timeout_ms"] = timeout_ms
    if "page_ref" in payload:
        target = self.web_page_state.resolve_page(payload.pop("page_ref"))
        if target is None:
            return business_error(3, "stale_page_reference", message="网页对象已失效")
        for key in ("mode", "page_url", "targetBrowser", "targetSessionId", "targetTabId"):
            payload.pop(key, None)
        payload.update(target)
        payload["live_page"] = True
    payload.setdefault("command_timeout_ms", timeout_ms if timeout_ms != 0 else 5000)
    try:
        raw = self.web_bridge.browser_command(command, **payload)
    except Exception as exc:
        failed = _web_business_error(5, "web_bridge_unavailable")
        failed["log_lines"] = [str(exc)]
        return _web_browser_result_from_error(failed)
    result = _web_browser_from_bridge(raw)
    if "page_ref" in params and command != "close" and self.web_page_state.resolve_page(params["page_ref"]) is None:
        return business_error(3, "stale_page_reference", message="网页对象已失效")
    if result.get("trace_info") == "web_browser_command_timeout" and command in {
        "get_active", "navigate", "reload", "back", "forward", "wait_ready",
    }:
        result["message"] = "等待页面加载超时"
    elif result.get("trace_info") == "web_browser_command_timeout" and command == "close":
        result["message"] = "关闭网页超时，页面可能无响应"
    if command in {"get_active", "get_info"} and not result.get("error"):
        return self._public_web_pages(result, params, many=False)
    return _public_web_bridge_payload(result, {"element_ref": {}}) if "page_ref" in params else result

function canProbeDocumentReady(tab) {
  const raw = String(tab && tab.url || "").trim();
  const url = raw.toLowerCase();
  if (url.startsWith("chrome://") || url.startsWith("chrome-extension://") || url.startsWith("edge://") || url.startsWith("devtools://") || url.startsWith("about:") || url.startsWith("view-source:")) {
    return false;
  }
  if (url.startsWith("file://")) return true;
  if (!url.startsWith("http://") && !url.startsWith("https://")) return false;
  try {
    const parsed = new URL(raw);
    const host = parsed.hostname.toLowerCase();
    const path = parsed.pathname || "";
    if (host === "chromewebstore.google.com") return false;
    if (host === "microsoftedge.microsoft.com" && path.includes("/addons")) return false;
    return true;
  } catch (_error) {
    return false;
  }
}
async function checkTabLoadFailure(tab) {
  if (!tab || tab.id == null) return;
  if (/^(chrome|edge)-error:/i.test(String(tab.url || ""))) {
    throw new Error("web_page_load_failed");
  }
  if (!canProbeDocumentReady(tab) || !chrome.webNavigation?.getFrame) return;
  // Read browser-owned frame state: an error document cannot reliably run a
  // content probe, and tabs.url can still contain the failed HTTP address.
  const frame = await chrome.webNavigation.getFrame({ tabId: tab.id, frameId: 0 });
  if (frame && frame.errorOccurred && !tab.pendingUrl) {
    throw new Error("web_page_load_failed");
  }
}
async function probeTabDocumentReady(tab, probeMs) {
  if (!tab || tab.id == null || !canProbeDocumentReady(tab)) return true;
  if (!chrome.scripting || typeof chrome.scripting.executeScript !== "function") return true;
  try {
    const out = await Promise.race([
      chrome.scripting.executeScript({
        target: { tabId: tab.id, frameIds: [0] },
        func: () => {
          const nav = performance.getEntriesByType && performance.getEntriesByType("navigation")[0];
          const loadEventEnd = nav ? nav.loadEventEnd : performance.timing && performance.timing.loadEventEnd;
          return document.readyState === "complete" && Number(loadEventEnd || 0) > 0;
        }
      }),
      sleep(Math.max(0, probeMs || 0)).then(() => null)
    ]);
    return Array.isArray(out) && out[0] && out[0].result === true;
  } catch (_error) {
    return false;
  }
}

